import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Main instance = new Main();
        instance.runProgram();
    }

    private void runProgram() throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(System.out);

        int testCaseCount = Integer.parseInt(reader.readLine());

        for (int caseIndex = 1; caseIndex <= testCaseCount; caseIndex++) {
            String line = reader.readLine();
            int firstSpace = line.indexOf(' ');
            int N = Integer.parseInt(line.substring(0, firstSpace));
            String inputString = line.substring(firstSpace + 1);
            char[] chars = inputString.toCharArray();

            int sequenceLength = 0, insideParentheses = 0;
            int wordCountInsideParens = 0, longestSequence = 0;

            for (int i = 0; i < chars.length; i++) {
                char current = chars[i];
                if (current == '_') {
                    if (insideParentheses == 0) {
                        longestSequence = Math.max(longestSequence, sequenceLength);
                    } else if (sequenceLength > 0) {
                        wordCountInsideParens++;
                    }
                    sequenceLength = 0;
                } else if (current == '(') {
                    insideParentheses = 1;
                    longestSequence = Math.max(longestSequence, sequenceLength);
                    sequenceLength = 0;
                } else if (current == ')') {
                    insideParentheses = 0;
                    if (sequenceLength > 0) {
                        wordCountInsideParens++;
                    }
                    sequenceLength = 0;
                } else {
                    sequenceLength++;
                }
                if (insideParentheses == 0) {
                    longestSequence = Math.max(longestSequence, sequenceLength);
                }
            }

            writer.println(longestSequence + " " + wordCountInsideParens);
        }

        writer.flush();
        writer.close();
        reader.close();
    }
}
